        assert!(admitted);
        assert!(!overflowed);
        assert_eq!(used, 4);

        let (admitted, overflowed, used) = with_limit_usage(3, || reserve_active_required(4));
        assert!(!admitted);
        assert!(overflowed);
        assert_eq!(used, 0);
        assert!(reserve_active_required(usize::MAX));
