struct Budget {
    initial: usize,
    remaining: Cell<usize>,
    floor: Cell<usize>,
    overflowed: Cell<bool>,
    first_refusal: Cell<Option<ReservationRefusal>>,
    first_site: Cell<Option<ReservationSite>>,
    stage: Cell<Option<ReservationStage>>,
}

thread_local! {
    static ACTIVE: RefCell<Option<Rc<Budget>>> = const { RefCell::new(None) };
}

pub(crate) fn with_limit<T>(limit: usize, operation: impl FnOnce() -> T) -> (T, bool) {
    let (value, overflowed, _) = with_limit_usage(limit, operation);
    (value, overflowed)
}

pub(crate) fn with_limit_usage<T>(limit: usize, operation: impl FnOnce() -> T) -> (T, bool, usize) {
    let (value, overflowed, consumed, _) = with_limit_usage_refusal(limit, operation);
    (value, overflowed, consumed)
}

pub(crate) fn with_limit_usage_refusal<T>(
    limit: usize,
    operation: impl FnOnce() -> T,
) -> (T, bool, usize, Option<ReservationRefusal>) {
    struct Restore {
        previous: Option<Rc<Budget>>,
        current: Rc<Budget>,
        initial: usize,
    }
    impl Drop for Restore {
        fn drop(&mut self) {
            let consumed = self.initial.saturating_sub(self.current.remaining.get());
            let previous = self.previous.take();
            ACTIVE.with(|active| {
                active.replace(previous.clone());
            });
            if let Some(parent) = previous {
                if !reserve(Some(&parent), consumed) {
                    record_refusal(&parent, consumed);
                    // A refused reservation normally means nothing was
                    // written, but here the child already emitted the bytes:
                    // they cannot be un-spent. Charge the parent anyway, so
                    // `consumed` and `active_remaining` stay truthful, and
                    // report the refusal.
                    let remaining = parent.remaining.get();
                    parent.remaining.set(remaining.saturating_sub(consumed));
                    #[cfg(test)]
                    stage_debits::debit(&parent, remaining.min(consumed));
                    parent.overflowed.set(true);
                }
            }
        }
    }
    let parent = active();
    let effective_limit = parent
        .as_ref()
        .map_or(limit, |budget| limit.min(budget.remaining.get()));
    let budget = Rc::new(Budget {
        initial: effective_limit,
        remaining: Cell::new(effective_limit),
        floor: Cell::new(0),
        overflowed: Cell::new(false),
        first_refusal: Cell::new(None),
        first_site: Cell::new(None),
        stage: Cell::new(None),
    });
    let previous = ACTIVE.with(|active| active.replace(Some(Rc::clone(&budget))));
    let restore = Restore {
        previous,
        current: Rc::clone(&budget),
        initial: effective_limit,
    };
    let value = operation();
    let overflowed = budget.overflowed.get();
    let consumed = effective_limit.saturating_sub(budget.remaining.get());
    let refusal = budget.first_refusal.get();
    drop(restore);
    (value, overflowed, consumed, refusal)
}

/// Compiler-owned call-site evidence, never a payer or source identity.
pub(crate) type ReservationSite = &'static std::panic::Location<'static>;

pub(crate) fn with_limit_usage_refusal_site<T>(
    limit: usize,
    operation: impl FnOnce() -> T,
) -> (
    T,
    bool,
    usize,
    Option<ReservationRefusal>,
    Option<ReservationSite>,
) {
    let ((value, site), overflowed, consumed, refusal) = with_limit_usage_refusal(limit, || {
        let value = operation();
        let site = active().and_then(|budget| budget.first_site.get());
        (value, site)
    });
    (value, overflowed, consumed, refusal, site)
}

fn active() -> Option<Rc<Budget>> {
    ACTIVE.with(|active| active.borrow().clone())
}

#[track_caller]
fn record_refusal(budget: &Budget, length: usize) {
    if budget.first_refusal.get().is_none() {
        #[cfg(test)]
        stage_debits::refusal(budget, length);
        budget.first_site.set(Some(std::panic::Location::caller()));
        budget.first_refusal.set(Some(ReservationRefusal {
            requested: length,
            remaining: budget.remaining.get(),
            floor: budget.floor.get(),
            stage: budget.stage.get(),
        }));
    }
}

/// A stage belongs to the current budget only. Nested budgets start unlabelled,
/// and unwind restores the previous stage before the next reservation.
pub(crate) fn with_reservation_stage<T>(
    stage: ReservationStage,
    operation: impl FnOnce() -> T,
) -> T {
    let restore = reservation_stage_guard(stage);
    let value = operation();
    drop(restore);
    value
}

/// Fixed-size restoration handle. Cloning the existing budget Rc allocates no
/// backing, and the handle never changes budget ownership or refusal selection.
pub(crate) struct ReservationStageGuard(Option<(Rc<Budget>, Option<ReservationStage>)>);
impl Drop for ReservationStageGuard {
    fn drop(&mut self) {
        if let Some((budget, previous)) = self.0.take() {
            budget.stage.set(previous);
        }
    }
}
pub(crate) fn reservation_stage_guard(stage: ReservationStage) -> ReservationStageGuard {
    ReservationStageGuard(active().map(|budget| {
        let previous = budget.stage.replace(Some(stage));
        (budget, previous)
    }))
}

/// Classify only the otherwise unlabelled outer loan-storage operation. An
/// existing semantic phase always wins; no new owner, state or debit is made.
pub(crate) fn loan_allocation_stage_guard(stage: ReservationStage) -> ReservationStageGuard {
    ReservationStageGuard(active().and_then(|budget| {
        if budget.stage.get() != Some(ReservationStage::CanonicalLoanStorage) {
            return None;
        }
        let previous = budget.stage.replace(Some(stage));
        Some((budget, previous))
    }))
}

macro_rules! staged {
    ($stage:ident, $operation:expr) => {
        $crate::bounded_output::with_reservation_stage(
            $crate::bounded_output::ReservationStage::$stage,
            || $operation,
        )
    };
}
pub(crate) use staged;

#[track_caller]
fn reserve(budget: Option<&Budget>, length: usize) -> bool {
    if budget.is_some_and(|budget| budget.overflowed.get()) {
        return false;
    }
    reserve_optional(budget, length)
}

#[track_caller]
fn reserve_optional(budget: Option<&Budget>, length: usize) -> bool {
    let Some(budget) = budget else {
        return true;
    };
    // A zero-sized retry cannot authenticate an already refused account.
    // Positive optional writes can still consume a reserved error trailer;
    // they never clear the selected refusal or restore required admission.
    if length == 0 && budget.overflowed.get() {
        return false;
    }
    let remaining = budget.remaining.get();
    if length > remaining {
        record_refusal(budget, length);
        budget.overflowed.set(true);
        return false;
    }
    if length
        .checked_add(budget.floor.get())
        .is_none_or(|required| required > remaining)
    {
        return false;
    }
    budget.remaining.set(remaining - length);
    #[cfg(test)]
    stage_debits::debit(budget, length);
    true
}

pub(crate) fn reserve_active(length: usize) -> bool {
    let budget = active();
    reserve_optional(budget.as_deref(), length)
}

/// Read-only eligibility for a prospective required reservation. This grants
/// no storage, spends no bytes and leaves the original refusal frontier intact.
pub(crate) fn active_required_fits(length: usize) -> bool {
    active().is_none_or(|budget| {
        !budget.overflowed.get()
            && length
                .checked_add(budget.floor.get())
                .is_some_and(|required| required <= budget.remaining.get())
    })
}

/// Required work cannot turn a reserved-floor refusal into successful output.
/// Preserve the ordinary reservation debit while making every refusal sticky.
#[track_caller]
pub(crate) fn reserve_active_required(length: usize) -> bool {
    let budget = active();
    if budget
        .as_ref()
        .is_some_and(|budget| budget.overflowed.get())
    {
        return false;
    }
    let admitted = reserve(budget.as_deref(), length);
    if !admitted {
        if let Some(budget) = budget {
            record_refusal(&budget, length);
            budget.overflowed.set(true);
        }
    }
    admitted
}

/// Fail a required allocator frontier without manufacturing another allocation
/// request. Already selected receipts and actual debits remain unchanged.
#[track_caller]
pub(crate) fn refuse_active_required(requested: usize) {
    if let Some(budget) = active() {
        record_refusal(&budget, requested);
        budget.overflowed.set(true);
    }
}

pub(crate) fn reserve_active_preserving(length: usize, floor: usize) -> bool {
    let budget = active();
    let Some(budget) = budget.as_deref() else {
        return true;
    };
    let floor = floor.max(budget.floor.get());
    let Some(required) = length.checked_add(floor) else {
        return false;
    };
    if required > budget.remaining.get() {
        return false;
    }
    reserve_optional(Some(budget), length)
}

pub(crate) fn set_active_floor(floor: usize) -> bool {
    let Some(budget) = active() else {
        return true;
    };
    if floor > budget.remaining.get() {
        return false;
    }
    budget.floor.set(floor);
    true
}

pub(crate) fn clear_active_floor() {
    if let Some(budget) = active() {
        budget.floor.set(0);
    }
}

pub(crate) fn active_remaining() -> Option<usize> {
    active().map(|budget| budget.remaining.get())
}

/// Infallible bounded helpers may return an empty carrier after refusal.
/// Publication boundaries must reject that sticky state even when their
/// surrounding operation otherwise returned success.
pub(crate) fn active_refused() -> bool {
    active().is_some_and(|budget| budget.overflowed.get())
}

pub(crate) fn active_limit() -> Option<usize> {
    active().map(|budget| budget.initial)
}

fn reserve_sink(captured: Option<&Rc<Budget>>, length: usize) -> bool {
    let current = active();
    let budget = current.as_deref().or_else(|| captured.map(Rc::as_ref));
    reserve(budget, length)
}

fn reserve_optional_sink(captured: Option<&Rc<Budget>>, length: usize) -> bool {
    let current = active();
    reserve_optional(
        current.as_deref().or_else(|| captured.map(Rc::as_ref)),
        length,
    )
}

/// Formats `arguments` in one pass, charging every append to the active
/// budget before it is written.
///
/// Each placeholder's formatter runs exactly once, so a formatter that emits
/// different bytes on different invocations cannot return bytes it was not
/// charged for. A refused append stops formatting. Bytes already appended stay
/// charged: the work was done even though the artifact is discarded.
///
/// Failure is never a successful artifact. A refused append, or a formatter
/// that returns `fmt::Error` after a partial write, yields an empty string and
/// fails the active budget closed through its overflow flag. Outside any
/// budget a formatter error panics, as `std::format!` does, rather than
/// publishing partial text.
pub(crate) fn budgeted_format(arguments: fmt::Arguments<'_>) -> String {
    let budget = active();
    match format_within(budget.as_deref(), arguments) {
        Ok(output) => output,
        Err(FormatFailure::Refused) => String::new(),
        Err(FormatFailure::Formatter) => match budget {
            Some(budget) => {
                budget.overflowed.set(true);
                String::new()
            }
            None => panic!("a formatting trait implementation returned an error"),
        },
    }
}

/// Why single-pass formatting produced no artifact.
#[derive(Debug, PartialEq, Eq)]
enum FormatFailure {
    /// The budget refused an append. `reserve` has already recorded whether
    /// that refusal was an overflow or a reserved-floor boundary.
    Refused,
    /// A formatter returned `fmt::Error` on its own.
    Formatter,
}

fn format_within(
    budget: Option<&Budget>,
    arguments: fmt::Arguments<'_>,
) -> Result<String, FormatFailure> {
    struct ReservingWriter<'a> {
        budget: Option<&'a Budget>,
        output: String,
        refused: bool,
    }
    impl fmt::Write for ReservingWriter<'_> {
        fn write_str(&mut self, value: &str) -> fmt::Result {
            if self.refused || !reserve(self.budget, value.len()) {
                self.refused = true;
                return Err(fmt::Error);
            }
            self.output.push_str(value);
            Ok(())
        }
    }
    let mut writer = ReservingWriter {
        budget,
        output: String::new(),
        refused: false,
    };
    match writer.write_fmt(arguments) {
        Ok(()) if !writer.refused => Ok(writer.output),
        _ if writer.refused => Err(FormatFailure::Refused),
        _ => Err(FormatFailure::Formatter),
    }
}

pub(crate) fn budgeted_join(values: impl IntoIterator<Item = String>, separator: &str) -> String {
    let values = values.into_iter().collect::<Vec<_>>();
    join_slices(&values, separator)
}

pub(crate) fn budgeted_clone(value: &str) -> String {
    let budget = active();
    if !reserve(budget.as_deref(), value.len()) {
        return String::new();
    }
    value.to_owned()
}

pub(crate) trait BudgetedJoin {
    fn budgeted_join(&self, separator: &str) -> String;
}

impl<T: AsRef<str>> BudgetedJoin for [T] {
    fn budgeted_join(&self, separator: &str) -> String {
        join_slices(self, separator)
    }
}

fn join_slices<T: AsRef<str>>(values: &[T], separator: &str) -> String {
    let length = values
        .iter()
        .try_fold(0usize, |length, value| {
            length.checked_add(value.as_ref().len())
        })
        .and_then(|length| {
            separator
                .len()
                .checked_mul(values.len().saturating_sub(1))
                .and_then(|separators| length.checked_add(separators))
        });
    let budget = active();
    let Some(length) = length else {
        if let Some(budget) = budget {
            budget.overflowed.set(true);
        }
        return String::new();
    };
    if !reserve(budget.as_deref(), length) {
        return String::new();
    }
    let mut output = String::with_capacity(length);
    for (index, value) in values.iter().enumerate() {
        if index > 0 {
            output.push_str(separator);
        }
        output.push_str(value.as_ref());
    }
    output
}

pub(crate) mod classifier_string;

pub(crate) struct CappedString {
    bytes: String,
    budget: Option<Rc<Budget>>,
}

impl CappedString {
    pub(crate) fn new() -> Self {
        Self {
            bytes: String::new(),
            budget: active(),
        }
    }

    #[cfg(test)]
    pub(crate) fn allocated_capacity(&self) -> usize {
        self.bytes.capacity()
    }

    pub(crate) fn push_str(&mut self, value: &str) {
        if reserve_sink(self.budget.as_ref(), value.len()) {
            self.bytes.push_str(value);
        }
    }

    pub(crate) fn push(&mut self, value: char) {
        if reserve_sink(self.budget.as_ref(), value.len_utf8()) {
            self.bytes.push(value);
        }
    }

    pub(crate) fn into_string(self) -> String {
        self.bytes
    }
}

impl fmt::Write for CappedString {
    fn write_str(&mut self, value: &str) -> fmt::Result {
        self.push_str(value);
        Ok(())
    }
}

pub(crate) struct CappedVec {
    bytes: Vec<u8>,
    budget: Option<Rc<Budget>>,
}

impl CappedVec {
    pub(crate) fn new() -> Self {
        Self {
            bytes: Vec::new(),
            budget: active(),
        }
    }

    pub(crate) fn from_slice(value: &[u8]) -> Self {
        let mut output = Self::new();
        output.extend_from_slice(value);
        output
    }

    pub(crate) fn push(&mut self, value: u8) {
        if reserve_optional_sink(self.budget.as_ref(), 1) {
            self.bytes.push(value);
        }
    }

    pub(crate) fn extend<const N: usize>(&mut self, values: [u8; N]) {
        self.extend_from_slice(&values);
    }

    pub(crate) fn extend_from_slice(&mut self, values: &[u8]) {
        if reserve_optional_sink(self.budget.as_ref(), values.len()) {
            self.bytes.extend_from_slice(values);
        }
    }

    pub(crate) fn len(&self) -> usize {
        self.bytes.len()
    }

    pub(crate) fn into_vec(self) -> Vec<u8> {
        self.bytes
    }
}

impl Deref for CappedVec {
    type Target = [u8];

    fn deref(&self) -> &Self::Target {
        &self.bytes
    }
}

#[cfg(test)]
mod tests {
    use std::panic::{catch_unwind, AssertUnwindSafe};

    use super::{
        active_limit, active_remaining, budgeted_clone, budgeted_format, budgeted_join,
        clear_active_floor, reserve_active, reserve_active_preserving, reserve_active_required,
        set_active_floor, with_limit, with_limit_usage, BudgetedJoin as _, CappedString, CappedVec,
    };

    /// Emits `first` on its first invocation and `later` on every other one,
    /// counting invocations.
    struct Changing {
        calls: std::cell::Cell<usize>,
        first: &'static str,
        later: &'static str,
    }

    impl Changing {
        fn new(first: &'static str, later: &'static str) -> Self {
            Self {
                calls: std::cell::Cell::new(0),
                first,
                later,
            }
        }
    }

    impl std::fmt::Display for Changing {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            let invocation = self.calls.get();
            self.calls.set(invocation + 1);
            f.write_str(if invocation == 0 {
                self.first
            } else {
                self.later
            })
        }
    }

    /// Hides a literal from `format_args!`, which would otherwise inline it
    /// into the template and merge adjacent pieces into one append.
    fn piece(value: &str) -> &str {
        std::hint::black_box(value)
    }

    /// Writes a prefix and then fails, as a broken formatter may.
    struct PartialThenError(&'static str);

    impl std::fmt::Display for PartialThenError {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            f.write_str(self.0)?;
            Err(std::fmt::Error)
        }
    }

    #[test]
    fn exact_limit_succeeds_and_over_limit_fails_closed() {
        let (exact, overflowed) = with_limit(4, || {
            let mut output = CappedString::new();
            output.push_str("four");
            output.into_string()
        });
        assert_eq!(exact, "four");
        assert!(!overflowed);

        let (over, overflowed) = with_limit(3, || {
            let mut output = CappedString::new();
            output.push_str("four");
            output.into_string()
        });
        assert_eq!(over, "");
        assert!(overflowed);
    }

    #[test]
    fn join_length_is_checked_and_budgeted() {
        let (joined, overflowed) =
            with_limit(5, || budgeted_join(["ab".to_owned(), "cd".to_owned()], ","));
        assert_eq!(joined, "ab,cd");
        assert!(!overflowed);

        let (joined, overflowed) =
            with_limit(4, || budgeted_join(["ab".to_owned(), "cd".to_owned()], ","));
        assert_eq!(joined, "");
        assert!(overflowed);
    }

    #[test]
    fn nested_budget_debits_parent_and_parent_sink_uses_child() {
        let (_, parent_overflowed) = with_limit(5, || {
            let mut parent_sink = CappedString::new();
            let (_, child_overflowed) = with_limit(3, || parent_sink.push_str("four"));
            assert!(child_overflowed);
            parent_sink.push_str("five!");
            assert_eq!(parent_sink.into_string(), "five!");
        });
        assert!(!parent_overflowed);

        let (_, parent_overflowed) = with_limit(5, || {
            let (_, child_overflowed) = with_limit(4, || {
                let mut output = CappedString::new();
                output.push_str("four");
            });
            assert!(!child_overflowed);
            let mut output = CappedString::new();
            output.push_str("xx");
        });
        assert!(parent_overflowed);
    }

    #[test]
    fn panic_restores_and_debits_parent_budget() {
        let (_, parent_overflowed) = with_limit(5, || {
            let result = catch_unwind(AssertUnwindSafe(|| {
                let _ = with_limit(4, || {
                    let mut output = CappedString::new();
                    output.push_str("four");
                    panic!("injected");
                });
            }));
            assert!(result.is_err());
            let mut output = CappedString::new();
            output.push_str("xx");
        });
        assert!(parent_overflowed);
    }

    #[test]
    fn usage_reports_exact_debits_and_preserves_nested_restoration() {
        let ((child_overflowed, child_used), parent_overflowed, parent_used) =
            with_limit_usage(7, || {
                let (_, child_overflowed, child_used) = with_limit_usage(4, || {
                    let mut output = CappedString::new();
                    output.push_str("abc");
                });
                let mut output = CappedString::new();
                output.push_str("defg");
                (child_overflowed, child_used)
            });
        assert!(!child_overflowed);
        assert_eq!(child_used, 3);
        assert!(!parent_overflowed);
        assert_eq!(parent_used, 7);

        let (_, overflowed, used) = with_limit_usage(2, || {
            let mut output = CappedString::new();
            output.push_str("abc");
        });
        assert!(overflowed);
        assert_eq!(used, 0);

        let (_, overflowed, used) = with_limit_usage(3, || {
            let mut output = CappedString::new();
            output.push_str("xyz");
        });
        assert!(!overflowed);
        assert_eq!(used, 3);
    }

    #[test]
