            output.push_str("éé");
            output.into_string()
        });
        assert_eq!(output, "");
        assert!(overflowed);

        // A four-byte code point does not fit a three-byte budget at all.
        let (output, overflowed) = with_limit(3, || {
            let mut output = CappedString::new();
