    }

    #[test]
    fn formatting_at_the_cap_succeeds_and_one_byte_over_fails_closed() {
        let (text, overflowed, used) = with_limit_usage(3, || {
            budgeted_format(format_args!("{}{}", piece("ab"), piece("c")))
        });
        assert_eq!(text, "abc");
        assert!(!overflowed);
        assert_eq!(used, 3);

